#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash execution tool and human confirmation
"""

import os
import sys
import json
import subprocess
from typing import List, Dict, Optional
import anthropic
from anthropic.types import Message, MessageParam, ToolParam, ToolUseBlock, TextBlock
from anthropic.types.tool_use_block_param import ToolUseBlockParam


class BashTool:
    """Bash execution tool with human confirmation"""

    @staticmethod
    def get_definition() -> ToolParam:
        return ToolParam(
            name="run_bash",
            description="Execute a bash command. Requires human confirmation before execution.",
            input_schema={
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        )

    @staticmethod
    def execute(command: str) -> str:
        """Execute bash command with human confirmation"""
        print(f"\n🔧 Tool Request: run_bash")
        print(f"Command: {command}")
        print("-" * 50)

        # Ask for confirmation
        while True:
            response = input("Execute this command? (y/n): ").lower().strip()
            if response in ['y', 'yes']:
                break
            elif response in ['n', 'no']:
                return "Command execution cancelled by user."
            else:
                print("Please enter 'y' or 'n'")

        try:
            # Execute the command
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )

            output = result.stdout
            if result.stderr:
                output += f"\n\nSTDERR:\n{result.stderr}"

            if result.returncode != 0:
                output += f"\n\nReturn code: {result.returncode}"

            return output if output else "Command executed successfully (no output)"

        except subprocess.TimeoutExpired:
            return "Command timed out after 30 seconds"
        except Exception as e:
            return f"Error executing command: {str(e)}"


class AgenticLoop:
    """Minimal agentic loop with Anthropic API"""

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.environ.get("ANTHROPIC_API_KEY")
        if not self.api_key:
            raise ValueError("API key must be provided or set in ANTHROPIC_API_KEY environment variable")

        self.client = anthropic.Anthropic(api_key=self.api_key)
        self.tools = [BashTool.get_definition()]
        self.messages: List[MessageParam] = []

    def run(self, initial_prompt: str):
        """Run the agentic loop"""
        print("🤖 Starting agentic loop...")
        print(f"Initial task: {initial_prompt}\n")

        # Add initial user message
        self.messages.append({
            "role": "user",
            "content": initial_prompt
        })

        while True:
            try:
                # Get response from Claude
                response = self.client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=4000,
                    messages=self.messages,
                    tools=self.tools,
                    temperature=0
                )

                # Add assistant message to history
                self.messages.append({
                    "role": "assistant",
                    "content": response.content
                })

                # Process the response
                tool_uses = []
                for block in response.content:
                    if isinstance(block, TextBlock):
                        print(f"\n🤖 Assistant: {block.text}")
                    elif isinstance(block, ToolUseBlock):
                        tool_uses.append(block)

                # Handle tool uses
                if tool_uses:
                    tool_results = []
                    for tool_use in tool_uses:
                        if tool_use.name == "run_bash":
                            result = BashTool.execute(tool_use.input["command"])
                            tool_results.append({
                                "type": "tool_result",
                                "tool_use_id": tool_use.id,
                                "content": result
                            })

                    # Add tool results to messages
                    if tool_results:
                        self.messages.append({
                            "role": "user",
                            "content": tool_results
                        })
                        continue

                # Ask if user wants to continue
                print("\n" + "-" * 50)
                while True:
                    next_action = input("\nWhat would you like to do? (continue/new task/quit): ").lower().strip()

                    if next_action in ['q', 'quit', 'exit']:
                        print("\n👋 Exiting agentic loop...")
                        return
                    elif next_action in ['c', 'continue']:
                        next_task = input("Enter your next instruction: ")
                        self.messages.append({
                            "role": "user",
                            "content": next_task
                        })
                        break
                    elif next_action in ['n', 'new', 'new task']:
                        # Clear messages and start fresh
                        self.messages = []
                        next_task = input("Enter your new task: ")
                        self.messages.append({
                            "role": "user",
                            "content": next_task
                        })
                        break
                    else:
                        print("Please enter 'continue', 'new task', or 'quit'")

            except KeyboardInterrupt:
                print("\n\n👋 Interrupted by user. Exiting...")
                return
            except Exception as e:
                print(f"\n❌ Error: {str(e)}")
                print("Continuing...")


def main():
    """Main entry point"""
    print("🚀 Minimal Agentic Loop with Anthropic API")
    print("=" * 50)

    # Check for API key
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("\n⚠️  Warning: ANTHROPIC_API_KEY environment variable not set.")
        api_key = input("Please enter your Anthropic API key: ").strip()
        if not api_key:
            print("❌ API key is required. Exiting...")
            sys.exit(1)
    else:
        api_key = None  # Will use environment variable
        print("✅ Using API key from environment variable")

    # Get initial task
    print("\nEnter your initial task for the agent.")
    print("Example: 'List the files in the current directory and create a simple hello.txt file'")
    initial_task = input("\nInitial task: ").strip()

    if not initial_task:
        print("❌ No task provided. Exiting...")
        sys.exit(1)

    # Create and run the agentic loop
    try:
        agent = AgenticLoop(api_key=api_key)
        agent.run(initial_task)
    except Exception as e:
        print(f"\n❌ Fatal error: {str(e)}")
        sys.exit(1)


if __name__ == "__main__":
    main()

